questions.solution:
def vector_add_grid(A, B, block_size):
    """Simulate vectorAdd<<<blocks, block_size>>>: every thread computes its global index and adds one element."""
    n = len(A)
    blocks = (n + block_size - 1) // block_size
    C = [None] * n
    for block_idx in range(blocks):
        for thread_idx in range(block_size):
            i = block_idx * block_size + thread_idx
            if i < n:
                C[i] = A[i] + B[i]
    return C
